// src/router.ts
import 'reflect-metadata';
import { Hono, type Context } from 'hono';
import { renderRoot } from './root';
import { PageOptions, Cossack, AuthenticatedUser } from '@cossackframework/core';
import { createApiHandler } from './api-handler';
// @ts-expect-error - this is a virtual module created by the vite plugin
import pages from 'virtual:cossack-pages';
// @ts-expect-error - this file is generated by vite and may not exist at design time
import manifest from '~/.vite/manifest.json';

export type PageModule = {
    [key: string]: new () => Cossack;
}

export function createApp() {
    const app = new Hono<{ Bindings: CloudflareBindings, Variables: { user?: AuthenticatedUser } }>();

    // TODO: Replace this with a real authentication middleware
    app.use('*', (c, next) => {
        c.set('user', { id: 'user-123', name: 'Alice' });
        return next();
    });

    // A generic route for all provider-based WebSocket connections
    app.get('/ws/:provider/:id', async (c) => {
        const user = c.get('user');
        if (!user) {
            return new Response('Unauthorized', { status: 401 });
        }

        const { provider, id: durableObjectId } = c.req.param();
        const componentId = c.req.query('componentId');

        if (!componentId) {
            return new Response('componentId query parameter is required', { status: 400 });
        }

        const doBinding = c.env.COSSACK_OBJECT;
        const id = doBinding.idFromString(durableObjectId);
        const stub = doBinding.get(id);

        const request = new Request(c.req.raw);
        request.headers.set('X-User-ID', user.id);
        request.headers.set('X-Component-Name', componentId);
        request.headers.set('X-Provider-Name', provider);
        request.headers.set('X-User-Data', JSON.stringify(user));

        return await stub.fetch(request);
    });

    app.post('/crpc', async (c) => {
        const { componentPath, action, state, payload } = await c.req.json();
        const user = c.get('user');

        const module = pages[componentPath];
        if (!module) {
            return c.json({ error: 'Component not found' }, 404);
        }

        const PageComponent = Object.values(module as object)[0] as new () => Cossack;
        if (!PageComponent) {
            return c.json({ error: 'Could not instantiate component' }, 500);
        }

        const componentInstance = new PageComponent() as any;
        
        // Bootstrap with an empty context, as this is an out-of-band request
        await componentInstance.bootstrap({ context: c, user, env: c.env, initialState: state });

        if (typeof componentInstance[action] !== 'function') {
            return c.json({ error: `Action '${action}' not found on component` }, 404);
        }

        const actionResult = await componentInstance[action](...(payload || []));

        // Check if the action resulted in a redirect
        const location = c.res.headers.get('Location');
        if (location) {
            return c.json({ _cossack_redirect: location });
        }

        // If the action returned a value, it might be a custom response
        if (actionResult instanceof Response) {
            return actionResult;
        }

        const newState = componentInstance.getPublicState();
        return c.json(newState);
    });

    // Build HTTP routes from the provided pages
    for (const path in pages) {
        const httpRoute = path
            .replace('/src/pages', '')
            .replace(/\.(ts|tsx|js|jsx)$/, '') // Strip file extension
            .replace(/\/index$/, '') // Handle index files
            .replace(/\[(\w+)\]/g, ':$1') || '/';

        const module = pages[path];
        const PageComponent = Object.values(module as object)[0] as new () => Cossack;
        if (!PageComponent) continue;

        const pageOptions: PageOptions | undefined = Reflect.getMetadata('page:options', PageComponent);
        const middlewares = pageOptions?.middlewares ?? [];

        // Handle standard, real-time SSR pages first
        if (pageOptions?.transport !== 'http') {
            Reflect.defineMetadata('cossack:durable-object-name', 'COSSACK_OBJECT', PageComponent);

            const ssrHandler = async (c: Context) => {
                const componentInstance = new PageComponent();
                const user = c.get('user');
                await componentInstance.bootstrap({ context: c, user, env: c.env, page: c.req.path });
                // init() is now called by the DO on first connect, so it's removed from the SSR path
                // to prevent a race condition where the SSR state is overwritten by the DO's initial state.
                const initialHtml = componentInstance.getInitialHtml();
                const initialState = componentInstance.getInitialState();
                const headTags = componentInstance.header();
                
                const channels = pageOptions?.channels || ['global'];
                const finalInitialState = { 
                    ...initialState, 
                    componentPath: path,
                    pathname: c.req.path,
                    channels: channels,
                };

                c.header('Content-Type', 'text/html');
                return c.body(renderRoot({ 
                    body: initialHtml, 
                    initialState: finalInitialState,
                    manifest: manifest,
                    headTags: headTags,
                }));
            };

            app.get(httpRoute, ...middlewares, ssrHandler);
            continue; // Move to the next page
        }

        // Handle HTTP Transport pages (APIs and Forms)
        const httpMethods = ['post', 'put', 'patch', 'delete'];
        for (const method of httpMethods) {
            if (method in PageComponent.prototype) {
                const handler = createApiHandler(PageComponent, method);
                (app as any)[method](httpRoute, ...middlewares, handler);
            }
        }

        // Special handling for GET: Render HTML if the component *itself* has a template, otherwise serve JSON.
        if (PageComponent.prototype.hasOwnProperty('template')) {
            const htmlHandler = async (c: Context) => {
                const componentInstance = new PageComponent() as any;
                const user = c.get('user');
                await componentInstance.bootstrap({ context: c, user, env: c.env, page: c.req.path });

                // Call get() or init() for data loading, implementing the alias
                if (typeof componentInstance.get === 'function') {
                    await componentInstance.get();
                } else if (typeof componentInstance.init === 'function') {
                    await componentInstance.init();
                }

                const initialHtml = componentInstance.getInitialHtml();
                const headTags = componentInstance.header();
                // Get the state *after* the data loading method has run
                const initialState = componentInstance.getInitialState();

                const finalInitialState = { 
                    ...initialState, 
                    componentPath: path,
                    pathname: c.req.path,
                };

                c.header('Content-Type', 'text/html');
                return c.body(renderRoot({ 
                    body: initialHtml, 
                    initialState: finalInitialState,
                    manifest: manifest,
                    headTags: headTags,
                }));
            };
            app.get(httpRoute, ...middlewares, htmlHandler);
        } else if ('get' in PageComponent.prototype) {
            const jsonHandler = createApiHandler(PageComponent, 'get');
            app.get(httpRoute, ...middlewares, jsonHandler);
        }
    }

    return app;
}